import {
  envVarName,
  readEnvCredential,
  resolveCredential,
} from "../src/auth/credentials.js";

const TOKEN_VARIABLE = "PETSTORE_CLIENT_TOKEN";

describe("credentials", () => {
  const saved = process.env[TOKEN_VARIABLE];

  afterEach(() => {
    if (saved === undefined) {
      delete process.env[TOKEN_VARIABLE];
    } else {
      process.env[TOKEN_VARIABLE] = saved;
    }
  });

  it("names an environment variable from the prefix and the field", () => {
    expect(envVarName("TOKEN")).toBe(TOKEN_VARIABLE);
  });

  it("reads the variable of the field", () => {
    process.env[TOKEN_VARIABLE] = "from-env";
    expect(readEnvCredential("TOKEN")).toBe("from-env");
  });

  it("treats an unset variable as absent", () => {
    delete process.env[TOKEN_VARIABLE];
    expect(readEnvCredential("TOKEN")).toBeUndefined();
  });

  it("treats an empty variable as unset", () => {
    process.env[TOKEN_VARIABLE] = "";
    expect(readEnvCredential("TOKEN")).toBeUndefined();
  });

  it("an explicit value wins over the environment", () => {
    process.env[TOKEN_VARIABLE] = "from-env";
    expect(resolveCredential("explicit", "TOKEN", "Token")).toBe("explicit");
  });

  it("falls back to the environment when no value is passed", () => {
    process.env[TOKEN_VARIABLE] = "from-env";
    expect(resolveCredential(undefined, "TOKEN", "Token")).toBe("from-env");
  });

  it("keeps an explicit empty string, so the caller sees the mistake", () => {
    process.env[TOKEN_VARIABLE] = "from-env";
    expect(resolveCredential("", "TOKEN", "Token")).toBe("");
  });

  it("names the variable when nothing supplies the value", () => {
    delete process.env[TOKEN_VARIABLE];
    expect(() => resolveCredential(undefined, "TOKEN", "Token")).toThrow(
      new TypeError(
        `Token is required: pass it explicitly or set ${TOKEN_VARIABLE}`,
      ),
    );
  });

  it("reads the variable once, when the credential is resolved", () => {
    process.env[TOKEN_VARIABLE] = "first";
    const resolved = resolveCredential(undefined, "TOKEN", "Token");
    process.env[TOKEN_VARIABLE] = "second";
    expect(resolved).toBe("first");
  });
});
